t.script:
(function(){
  var sidebarOpen = window.innerWidth &gt; 768;
  var notifOpen = false;
  var refreshSec = 30;
  var remaining = refreshSec;

  // Init sidebar on mobile
  if(window.innerWidth &lt;= 768){
    var sb = document.getElementById('vp-sidebar');
    if(sb) sb.style.transform = 'translateX(-100%)';
  }

  window.vpToggleSidebar = function(){
    var sb = document.getElementById('vp-sidebar');
    var main = document.getElementById('vp-main');
    var h1 = document.getElementById('vph1');
    var h2 = document.getElementById('vph2');
    var h3 = document.getElementById('vph3');
    sidebarOpen = !sidebarOpen;
    if(sidebarOpen){
      sb.style.transform = '';
      if(window.innerWidth &gt; 768) main.style.marginLeft = '220px';
      if(h1){ h1.style.transform=''; h2.style.opacity='1'; h3.style.transform=''; }
    } else {
      sb.style.transform = 'translateX(-100%)';
      if(window.innerWidth &gt; 768) main.style.marginLeft = '0';
      if(h1){ h1.style.transform='rotate(45deg) translate(4px,4px)'; h2.style.opacity='0'; h3.style.transform='rotate(-45deg) translate(4px,-4px)'; }
    }
  };

  window.vpToggleNotif = function(){
    notifOpen = !notifOpen;
    var panel = document.getElementById('vp-notif-panel');
    if(panel) panel.classList.toggle('open', notifOpen);
    var pp = document.getElementById('vp-profile-panel');
    if(pp) pp.classList.remove('open');
  };

  var profileOpen = false;
  window.vpToggleProfile = function(){
    profileOpen = !profileOpen;
    var pp = document.getElementById('vp-profile-panel');
    if(pp) pp.classList.toggle('open', profileOpen);
    var np = document.getElementById('vp-notif-panel');
    if(np) np.classList.remove('open');
    notifOpen = false;
  };

  window.vpClearNotif = function(){
    document.querySelectorAll('.vp-notif-item.unread').forEach(function(i){ i.classList.remove('unread'); });
    var dot = document.getElementById('vp-notif-dot');
    var badge = document.getElementById('vp-notif-badge');
    if(dot) dot.classList.remove('show');
    if(badge) badge.style.display = 'none';
  };

  document.addEventListener('click', function(e){
    if(notifOpen &amp;&amp; !e.target.closest('#vp-notif-panel') &amp;&amp; !e.target.closest('.vp-notif-btn')){
      notifOpen = false;
      var panel = document.getElementById('vp-notif-panel');
      if(panel) panel.classList.remove('open');
    }
    if(profileOpen &amp;&amp; !e.target.closest('#vp-profile-panel') &amp;&amp; !e.target.closest('.vp-avatar')){
      profileOpen = false;
      var pp = document.getElementById('vp-profile-panel');
      if(pp) pp.classList.remove('open');
    }
  });

  // Refresh countdown
  setInterval(function(){
    remaining--;
    var el = document.getElementById('vp-refresh-sec');
    if(el) el.textContent = remaining;
    if(remaining &lt;= 0){
      remaining = refreshSec;
      // Poll for new orders
      vpCheckNotifications();
    }
  }, 1000);

  // Poll notifications
  window.vpCheckNotifications = function(){
    fetch('/my/vendor/notifications/poll', {
      method: 'GET',
      headers: {'X-Requested-With': 'XMLHttpRequest'}
    })
    .then(function(r){ return r.json(); })
    .then(function(data){
      if(data.count > 0){
        var dot = document.getElementById('vp-notif-dot');
        var badge = document.getElementById('vp-notif-badge');
        var list = document.getElementById('vp-notif-list');
        if(dot) dot.classList.add('show');
        if(badge){ badge.textContent = data.count; badge.style.display = 'inline'; }
        if(list &amp;&amp; data.items){
          list.innerHTML = '';
          data.items.forEach(function(item){
            var div = document.createElement('div');
            div.className = 'vp-notif-item' + (item.unread ? ' unread' : '');
            div.innerHTML =
              '&lt;div class="vp-ni-icon" style="background:' + item.bg + ';color:' + item.color + '"&gt;&lt;i class="fa ' + item.icon + '"&gt;&lt;/i&gt;&lt;/div&gt;' +
              '&lt;div class="vp-ni-text"&gt;&lt;strong&gt;' + item.title + '&lt;/strong&gt;&lt;span&gt;' + item.body + '&lt;/span&gt;&lt;/div&gt;' +
              '&lt;span class="vp-ni-time"&gt;' + item.time + '&lt;/span&gt;';
            list.appendChild(div);
          });
        }
      }
    })
    .catch(function(){});
  };

  // Initial poll after 3s
  setTimeout(window.vpCheckNotifications, 3000);
})();

//
      document.addEventListener('DOMContentLoaded', function () {
        var btn = document.getElementById('vs_follow_btn');
        if (btn) {
          btn.addEventListener('click', function () {
            if (btn.getAttribute('data-login') === '1') { window.location.href = '/web/login?redirect=' + encodeURIComponent(window.location.pathname); return; }
            var slug = btn.getAttribute('data-slug');
            fetch('/store/' + slug + '/follow', {method:'POST', headers:{'Content-Type':'application/json'}, body: JSON.stringify({jsonrpc:'2.0', method:'call', params:{}})})
              .then(function(r){return r.json();}).then(function(res){ var d = res.result || res; var lbl = document.getElementById('vs_follow_label'); if (d && typeof d.following !== 'undefined') { lbl.textContent = d.following ? 'Following' : 'Follow'; } else { location.reload(); } }).catch(function(){ location.reload(); });
          });
        }
        var ft = document.getElementById('vs_flash_timer');
        if (ft) {
          var secs = parseInt(ft.getAttribute('data-seconds') || '0', 10);
          var ed = document.getElementById('vs_fd'), eh = document.getElementById('vs_fh'), em = document.getElementById('vs_fm'), es = document.getElementById('vs_fs');
          var pad = function (n) { return (n < 10 ? '0' : '') + n; };
          var tick = function () {
            if (secs < 0) secs = 0;
            var d = Math.floor(secs / 86400), h = Math.floor((secs % 86400) / 3600), m = Math.floor((secs % 3600) / 60), s = secs % 60;
            if (ed) ed.textContent = pad(d);
            if (eh) eh.textContent = pad(h);
            if (em) em.textContent = pad(m);
            if (es) es.textContent = pad(s);
            if (secs > 0) secs--;
          };
          tick(); setInterval(tick, 1000);
        }
        var ddT = document.getElementById('vs_cat_toggle'), ddM = document.getElementById('vs_cat_menu');
        if (ddT && ddM) {
          ddT.addEventListener('click', function(e){ e.preventDefault(); ddM.style.display = (ddM.style.display==='none'?'block':'none'); });
          document.addEventListener('click', function(e){ if(!document.getElementById('vs_cat_dd').contains(e.target)){ ddM.style.display='none'; } });
          ddM.querySelectorAll('.vs-cat-link').forEach(function(l){ l.addEventListener('click', function(e){ var el=document.querySelector(l.getAttribute('href')); if(el){ e.preventDefault(); ddM.style.display='none'; el.scrollIntoView({behavior:'smooth'}); } }); });
        }
      });
//

//
      document.addEventListener('DOMContentLoaded', function () {
        var add = document.getElementById('wd_add_line');
        if (add) {
          add.addEventListener('click', function (e) {
            e.preventDefault();
            var box = document.getElementById('wd_lines');
            var first = box.querySelector('div');
            var clone = first.cloneNode(true);
            clone.querySelector('input[name=qty]').value = 1;
            clone.querySelector('select[name=product_id]').value = '';
            box.appendChild(clone);
          });
        }
      });
//
